import {commission,audience,receive,authorize,lineage} from './model.js';
document.documentElement.classList.add('js');
document.querySelectorAll('.js-only').forEach(e=>e.hidden=false);
const $=id=>document.getElementById(id),put=(id,value)=>{if($(id))$(id).textContent=value}, money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
$('menu').addEventListener('click',()=>{const open=document.querySelector('.sidebar').classList.toggle('open');$('menu').setAttribute('aria-expanded',String(open));});
const stories=[['Commission reporting','/','payment commission rate hold payroll'],['Marketing audiences','/marketing/','audience consent transfer campaign reconcile'],['From form to CRM','/crm-webhook/','form webhook receipt duplicate retry notification'],['Authorized questions','/authorized-queries/','identity authorization access scope query'],['From change to report','/lineage/','lineage release build deploy refresh report']];
$('search').addEventListener('input',()=>{const q=$('search').value.trim().toLowerCase(),box=$('search-results');box.replaceChildren();box.hidden=!q;if(!q)return;const matches=stories.filter(x=>(x[0]+' '+x[2]).toLowerCase().includes(q));for(const [title,url] of matches){const a=document.createElement('a');a.href=url;a.textContent=title;box.append(a)}if(!matches.length){const p=document.createElement('p');p.textContent='No story found. Try “payment” or “refresh”.';box.append(p)}});
$('search').addEventListener('keydown',e=>{if(e.key==='Escape')$('search-results').hidden=true;if(e.key==='Enter')$('search-results').querySelector('a')?.click()});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('search-results').hidden=true});
function bind(id,fn){const form=$(id);if(form){form.addEventListener('input',()=>fn(form.elements));form.addEventListener('submit',e=>e.preventDefault());fn(form.elements)}}
bind('commission-controls',e=>{const r=commission({paid:Number(e.paid.value),games:Number(e.games.value),product:e.product.value,hold:e.hold.checked,matched:!e.unmatched.checked});e.paid.setAttribute('aria-invalid',String(Boolean(r.error)));if(r.error){put('c-summary',r.error);for(const id of ['c-rule','c-paid','c-unpaid','c-basis','c-calculated','c-formula','c-payable','c-period'])put(id,'—');return}put('c-rule',e.unmatched.checked?'No matching rule':`${e.games.value} games → ${r.rate}%`);put('c-paid',money(Number(e.paid.value)*100));put('c-unpaid',`${money(r.unpaid)} of the ticket remains unpaid.`);put('c-basis',`${money(r.basis)} commissionable`);put('c-calculated',e.unmatched.checked?'Needs review':`${money(r.calculated)} calculated`);put('c-formula',e.unmatched.checked?'No rate is assigned until a rule matches.':`${money(r.basis)} × ${r.rate}% = ${money(r.calculated)}.`);put('c-payable',e.unmatched.checked?'Not ready for payment':`${money(r.payable)} payable`);put('c-period',`${r.period} · ${e.product.value==='group'?'event':'payment'} date ${r.date}.`);put('c-summary',e.unmatched.checked?'No matching rule. Review the allocation before calculating payment.':e.hold.checked?`The hold keeps ${money(r.calculated)} calculated, with $0.00 payable.`:`${money(r.calculated)} calculated and ${money(r.payable)} payable. No hold applies.`);});
bind('audience-controls',e=>{e.reconciled.disabled=!e.transfer.checked;e.applied.disabled=!e.returned.checked;const r=audience({transfer:e.transfer.checked,reconciled:e.reconciled.checked,returned:e.returned.checked,applied:e.applied.checked});put('a-destination',r.destination.toLocaleString('en-US'));put('a-difference',`${r.missing} missing · ${r.retained} retained from earlier membership`);put('a-returned',r.withdrawals);put('a-eligible',r.nextEligible.toLocaleString('en-US'));put('a-status',!e.transfer.checked?'Changes have not reached the destination.':!e.reconciled.checked?'The transfer completed. Membership still differs.':r.withdrawals&&!e.applied.checked?'Membership reconciled. The returned withdrawals still need to change eligibility.':r.withdrawals?'Membership reconciled. Three withdrawals are applied to the next audience.':'Membership reconciled by ID. No new withdrawal events have returned.');});
let crm=receive({},'reset');document.querySelectorAll('[data-crm]').forEach(b=>b.addEventListener('click',()=>{crm=receive(crm,b.dataset.crm);put('r-attempts',crm.attempts);put('r-receipt',crm.receipt||'Not received');put('r-records',crm.opportunities);put('r-owner',crm.receipt?'Casey · Harbor sales':'Not assigned');put('r-notified',crm.notified?'Delivered':crm.receipt?'Failed · retry available':'Not sent');put('r-status',crm.message)}));
bind('auth-controls',e=>{const r=authorize({role:e.role.value,question:e.question.value,team:e.team.value,available:!e.unavailable.checked});put('q-answer',r.unavailable?'Unavailable':!r.allowed?(e.question.value==='ambiguous'&&e.team.value==='harbor'?'Clarification needed':'Access denied'):money(r.value*100));put('q-status',r.reason);put('q-sql',r.sql)});
const lineageMessages={current:'The deployed version and all three data stages agree.',build:'r13 passed its build, but the running site is still r12. Publishing is the next boundary.',source:'The source is a day behind. Later stages correctly reflect that older input.',model:'The warehouse is current. Refresh the reporting model to include October 20 output.'};
bind('lineage-controls',e=>{const r=lineage(e.scenario.value);for(const key of ['build','deployed','source','gold','model'])put('l-'+key,r[key]);put('l-report',r.report.toLocaleString('en-US'));put('l-status',lineageMessages[e.scenario.value])});

// Follow a diagram node to its existing detail without creating a second UI.
document.addEventListener('click',event=>{const a=event.target.closest('a[href^="#trace-"]');if(!a)return;const detail=document.getElementById(a.getAttribute('href').slice(1));if(!detail)return;for(let el=detail;el;el=el.parentElement){if(el.tagName==='DETAILS')el.open=true;} });
